        url = f"https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key={self.webhook_key}"
        payload = {
            "msgtype": "markdown",
            "markdown": {
                "content": self.content
            }
        }

        response = requests.post(url, json=payload, timeout=15)
        if response.status_code != 200:
            raise RuntimeError(f"请求企业微信接口 HTTP 失败, 状态码: {response.status_code}, 内容: {response.text}")

        res_json = response.json()
        if res_json.get('errcode') != 0:
            raise ValueError(f"企业微信返回业务错误: errcode={res_json.get('errcode')}, errmsg={res_json.get('errmsg')}")

        self.log.info("企业微信消息推送成功！")
        return res_json
